import java.util.*;

public class QueueBasics {

    // ========== 1. 循环队列（数组 + size 方案） ==========
    static class CircularQueue {
        private final int[] arr;
        private int front = 0;  // 队头下标
        private int size = 0;   // 当前元素个数（用于判空判满）
        private final int capacity;

        public CircularQueue(int capacity) {
            this.capacity = capacity;
            this.arr = new int[capacity];
        }

        /** 入队：rear = (front + size) % capacity */
        public boolean offer(int val) {
            if (isFull()) return false;
            int rear = (front + size) % capacity; // rear 由 front + size 推算
            arr[rear] = val;
            size++;
            return true;
        }

        /** 出队：front 取模前进 */
        public int poll() {
            if (isEmpty()) throw new RuntimeException("Queue is empty");
            int val = arr[front];
            front = (front + 1) % capacity;
            size--;
            return val;
        }

        public int peek() {
            if (isEmpty()) throw new RuntimeException("Queue is empty");
            return arr[front];
        }

        public boolean isEmpty() { return size == 0; }
        public boolean isFull()  { return size == capacity; }
    }

    // ========== 2. BFS 层序遍历 ==========
    static List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) return result;
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size(); // 当前层的节点数
            List<Integer> level = new ArrayList<>();
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            result.add(level);
        }
        return result;
    }

    // ========== 3. 滑动窗口最大值（单调递减 Deque） ==========
    static int[] maxSlidingWindow(int[] nums, int k) {
        if (nums == null || nums.length == 0) return new int[0];
        int n = nums.length;
        int[] result = new int[n - k + 1];
        Deque<Integer> dq = new ArrayDeque<>(); // 存下标，维护 nums[dq[i]] 单调递减
        for (int i = 0; i < n; i++) {
            // 1. 移除超出窗口左边界的下标
            while (!dq.isEmpty() && dq.peekFirst() < i - k + 1) dq.pollFirst();
            // 2. 移除队尾所有比 nums[i] 小的元素（维护单调递减）
            while (!dq.isEmpty() && nums[dq.peekLast()] < nums[i]) dq.pollLast();
            dq.offerLast(i);
            if (i >= k - 1) result[i - k + 1] = nums[dq.peekFirst()]; // 队头即窗口最大
        }
        return result;
    }

    // ========== 4. TopK（小顶堆保留前 k 大） ==========
    static int[] topK(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // 默认小顶堆
        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) minHeap.poll(); // 堆满时弹出最小，留下前 k 大
        }
        int[] result = new int[k];
        for (int i = k - 1; i >= 0; i--) result[i] = minHeap.poll();
        return result;
    }

    static class TreeNode {
        int val; TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    public static void main(String[] args) {
        // 循环队列演示
        CircularQueue cq = new CircularQueue(3);
        cq.offer(10); cq.offer(20); cq.offer(30);
        assert cq.isFull();
        cq.poll(); // 弹出 10，front 前进
        cq.offer(40); // rear 绕回，复用 slot 0
        assert cq.peek() == 20;

        // TopK 演示
        int[] top = topK(new int[]{3, 1, 5, 12, 2, 11}, 3);
        System.out.println(Arrays.toString(top)); // [5, 11, 12]

        // 滑动窗口演示
        int[] max = maxSlidingWindow(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3);
        System.out.println(Arrays.toString(max)); // [3, 3, 5, 5, 6, 7]
    }
}
